{
  "components": [
    {
      "type": "obligation",
      "quote": "The SFOE forwards the application documentation to the authorities represented in the Federal Spatial Planning Conference for comment within two months.",
      "gist": "SFOE must send application docs to Federal Spatial Planning Conference authorities for comments within two months."
    },
    {
      "type": "obligation",
      "quote": "Upon receipt of the feedback, the SFOE sets up a support group within two months.",
      "gist": "SFOE must establish a support group within two months after receiving feedback."
    },
    {
      "type": "obligation",
      "quote": "For the purpose of inspecting the potential planning zones, the SFOE may arrange for an on-site visit by the support group.",
      "gist": "SFOE may organize an on-site visit by the support group to inspect potential planning zones."
    },
    {
      "type": "obligation",
      "quote": "The latter then examines the application documents and recommends a planning zone, which has to be large enough to ensure that more than one planning corridor can be developed.",
      "gist": "Support group must examine documents and recommend a planning zone large enough for multiple corridors."
    }
  ]
}
